/** `InvoiceStatus` from the EuroDNS OpenAPI document. */
export const InvoiceStatusSchema = z.enum(["INTERNAL", "TO_PAY", "NOT_TO_PAY", "WAITING_PO_NUMBER", "PENDING_PAYMENT", "PENDING_PARTIAL_PAYMENT", "PARTIALLY_PAID", "PAID", "TO_REIMBURSE", "PENDING_REIMBURSEMENT", "PARTIALLY_REIMBURSED", "REIMBURSED", "CANCELLED"]).describe("The invoice status - CANCELLED: the invoice has been cancelled and should no longer be considered. - INTERNAL: the invoice is being processed by our system. - PAID: the invoice has been payed. No other operation is expected on this invoice. - PARTIALLY_PAID: the invoice has been partially paid, but the payment did not cover the invoice full price. Another payment is expected to cover the due leftover amount. - PARTIALLY_REIMBURSED: the invoice was paid, and then partially reimbursed, but the reimbursement did not cover the invoice full price. Another reimbursement is expected to cover the invoice paid amount. - PENDING_PARTIAL_PAYMENT: a payment not covering the full invoice price has been initiated, but has yet to be completed. - PENDING_PAYMENT: a payment covering the full invoice price has been initiated, but has yet to be completed. - PENDING_REIMBURSEMENT: a reimbursement has been initiated, but has yet to be completed. - REIMBURSED: the invoice has been reimbursed in its full paid amount. - TO_PAY: the invoice is outstanding and needs to be paid. - TO_REIMBURSE: the invoice reimbursement has not been initiated yet. - WAITING_PO_NUMBER: the invoice requires a P.O. number to be provided before being processed.");

